import assert from 'node:assert/strict';
if(process.env.ZEPTER_UI_FIXTURE!=='1'||process.env.ZEPTER_UI_QA!=='1')throw Error('Requires explicit isolated fixture and QA mode.');
const base='http://127.0.0.1:4002/api';
const session=await(await fetch(base+'/auth/refresh',{method:'POST'})).json();
assert.equal(session.accessToken,'isolated-ui-fixture');assert.equal(session.user.role,'manager');
let checks=0;
async function call(role,path,{method='GET',body,version,status=200}={}){
 const response=await fetch(base+path,{method,headers:{Authorization:'Bearer isolated-ui-fixture','X-Zepter-Fixture-Role':role,...(body?{'Content-Type':'application/json'}:{}),...(version?{'If-Match':'"'+version+'"'}:{})},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(10000)});
 assert.equal(response.status,status,role+' '+method+' '+path);checks++;return response.json();
}
const manager=session.user._id,sector=session.user.sector,employee='11'.repeat(12),day='2026-11-23';
const {project}=await call('manager','/projects',{method:'POST',status:201,body:{sectorId:sector,title:'Izolovani povezani tok',description:'Kompletna provera rada sektora.',ownerId:manager,memberIds:[employee],startDate:'2026-11-09',dueDate:'2026-12-20'}});
const {activity}=await call('manager','/activities/project/'+project._id,{method:'POST',status:201,body:{title:'Priprema rezultata',assigneeIds:[employee],dueDate:'2026-12-10'}});
await call('employee','/projects/'+project._id);
const update=await call('employee','/activities/'+activity._id,{method:'PATCH',version:activity.updatedAt,body:{status:'completed',progress:100,actualWork:'Završen povezani rezultat.',nextStep:'Predati izveštaj.'}});
assert.equal(update.projectProgress,100);
await call('employee','/activities/'+activity._id,{method:'PATCH',version:'old',body:{progress:20},status:409});
await call('employee','/worklogs',{method:'POST',status:201,body:{day,activityId:activity._id,done:'Završen povezani rezultat.',nextSteps:'Predati izveštaj.',minutes:90}});
const {comment:instruction}=await call('manager','/comments',{method:'POST',status:201,body:{targetType:'activity',targetId:activity._id,kind:'instruction',body:'Potvrdite rezultat i naredni korak.'}});
await call('employee','/comments',{method:'POST',status:201,body:{targetType:'activity',targetId:activity._id,parentId:instruction._id,body:'Rezultat je potvrđen.'}});
assert.equal((await call('manager','/comments?targetType=activity&targetId='+activity._id)).items.find(x=>x._id===instruction._id).responseStatus,'answered');
const {idea}=await call('employee','/ideas',{method:'POST',status:201,body:{title:'Unapređenje procesa',description:'Detaljan predlog zaposlenog.',benefit:'Brži rad.'}});
await call('president','/ideas/'+idea._id,{status:403});
const {idea:revision}=await call('manager','/ideas/'+idea._id+'/review',{method:'POST',version:idea.updatedAt,body:{action:'request_revision',note:'Dodati plan i troškove.'}});
const {idea:edited}=await call('employee','/ideas/'+idea._id,{method:'PATCH',version:revision.updatedAt,body:{description:'Dopunjen predlog, plan i troškovi.'}});
const {idea:resubmitted}=await call('employee','/ideas/'+idea._id+'/resubmit',{method:'POST',version:edited.updatedAt});
await call('manager','/ideas/'+idea._id+'/review',{method:'POST',version:resubmitted.updatedAt,body:{action:'forward',note:'Predlog je spreman za razmatranje.'}});
assert.equal((await call('president','/ideas/'+idea._id)).idea.description,'Dopunjen predlog, plan i troškovi.');
await call('manager','/ideas/'+idea._id+'/review',{method:'POST',body:{action:'forward'},status:409});
const prepare=await call('manager','/reports/prepare?type=weekly&day='+day);
assert.ok(prepare.generated.completed.some(x=>x.text==='Završen povezani rezultat.'));
const {report}=await call('manager','/reports',{method:'POST',status:201,body:{sectorId:sector,type:'weekly',day,results:'Potvrđeni rezultati sektora.',problems:'',nextSteps:'Naredna faza.'}});
await call('president','/reports/'+report._id,{status:403});
await call('manager','/reports/'+report._id+'/publish',{method:'POST',version:report.updatedAt});
const published=(await call('president','/reports/'+report._id)).report;
assert.equal(published.status,'published');assert.equal(published.results,'Potvrđeni rezultati sektora.');
assert.ok(published.generated.completed.some(x=>x.text==='Završen povezani rezultat.'));
await call('manager','/reports/'+report._id,{method:'PATCH',body:{results:'Nedozvoljena promena'},status:403});
await call('manager','/reports/'+report._id+'/publish',{method:'POST',status:409});
await call('employee','/reports/'+report._id,{status:403});
await call('employee','/worklogs/team',{status:403});
await call('manager','/projects/'+'f6'.repeat(12),{status:403});
const notifications=await call('president','/notifications?limit=50');
assert.equal(notifications.items.filter(x=>x.type==='idea_forwarded'&&x.link==='/ideas/'+idea._id).length,1);
assert.equal(notifications.items.filter(x=>x.type==='report_published'&&x.link==='/reports/'+report._id).length,1);
console.log(`OK ${checks} HTTP checks: manager → employee work → instruction/reply → idea revision/forward → published report → president, with negative authorization and duplicate guards. No MongoDB connection.`);
